insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
values
('Мединский курс (Том 1)', '1', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْقَرِيبِ: هَذَا (указательное слово «это/этот»)', '<b>Суть правила.</b> <b>هَذَا</b> употребляется с одним предметом или лицом мужского рода, находящимся близко: <b>هَذَا كِتَابٌ</b> — «Это книга». Отдельного слова «есть» в настоящем времени не требуется.<br><br><b>Дополнительное объяснение.</b> Это именное предложение <b>جُمْلَةٌ اِسْمِيَّةٌ</b>. <b>هَذَا</b> — указательное слово в позиции первого члена предложения, а следующее неопределённое существительное сообщает, что это за предмет. Алиф после <b>هَاء</b> произносится, но в стандартном написании слова не обозначается отдельной буквой: <b>هَذَا</b>, а не <b>هَاذَا</b>. Термины <b>الْمُبْتَدَأُ</b> и <b>الْخَبَرُ</b> вводятся позже, в уроках 13 и 17.<br><br><ul><li><b>هَذَا بَيْتٌ.</b> — Это дом. <b>هَذَا</b> указывает на близкий предмет; <b>بَيْتٌ</b> сообщает, что это за предмет.</li><li><b>هَذَا مُدَرِّسٌ.</b> — Это учитель. Слово <b>مُدَرِّسٌ</b> неопределённое и получает танвин.</li></ul>', 1, 'rule', 'Суть правила. هَذَا употребляется с одним предметом или лицом мужского рода, находящимся близко: هَذَا كِتَابٌ — «Это книга». Отдельного слова «есть» в настоящем времени не требуется. Дополнительное объяснение. Это именное предложение جُمْل'),
('Мединский курс (Том 1)', '1', 'مَا؟ وَمَنْ؟ (вопросы «что?» и «кто?»)', '<b>مَا هَذَا؟</b> спрашивает о предмете: «Что это?» <b>مَنْ هَذَا؟</b> спрашивает о человеке: «Кто это?»<br><br><ul><li><b>مَا هَذَا؟ هَذَا قَلَمٌ.</b> — Что это? Это ручка.</li><li><b>مَنْ هَذَا؟ هَذَا طَالِبٌ.</b> — Кто это? Это студент.</li></ul>', 2, 'rule', 'مَا هَذَا؟ спрашивает о предмете: «Что это?» مَنْ هَذَا؟ спрашивает о человеке: «Кто это?» مَا هَذَا؟ هَذَا قَلَمٌ. — Что это? Это ручка. مَنْ هَذَا؟ هَذَا طَالِبٌ. — Кто это? Это студент.'),
('Мединский курс (Том 1)', '1', 'هَمْزَةُ الِاسْتِفْهَامِ، نَعَمْ، لَا (вопросительная أَ, «да», «нет»)', 'Частица <b>أَ</b> ставится перед утверждением и превращает его в общий вопрос. Ответ: <b>نَعَمْ</b> — да; <b>لَا</b> — нет.<br><br><ul><li><b>أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ.</b> — Это дом? Да, это дом.</li><li><b>أَهَذَا كَلْبٌ؟ لَا، هَذَا قِطٌّ.</b> — Это собака? Нет, это кот.</li></ul>', 3, 'rule', 'Частица أَ ставится перед утверждением и превращает его в общий вопрос. Ответ: نَعَمْ — да; لَا — нет. أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ. — Это дом? Да, это дом. أَهَذَا كَلْبٌ؟ لَا، هَذَا قِطٌّ. — Это собака? Нет, это кот.'),
('Мединский курс (Том 1)', '1', 'التَّنْوِينُ وَالتَّنْكِيرُ (танвин и неопределённость)', 'Окончание <b>ـٌ</b> в формах <b>كِتَابٌ، بَيْتٌ، مَسْجِدٌ</b> показывает неопределённость и именительный падеж. Оно не переводится отдельным словом. <b>Дополнительное объяснение:</b> это <b>تَنْوِينُ الضَّمِّ</b>, а существительное здесь обычно является именительной частью сообщения.', 4, 'rule', 'Окончание ـٌ в формах كِتَابٌ، بَيْتٌ، مَسْجِدٌ показывает неопределённость и именительный падеж. Оно не переводится отдельным словом. Дополнительное объяснение: это تَنْوِينُ الضَّمِّ , а существительное здесь обычно является именительной '),
('Мединский курс (Том 1)', '2', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْبَعِيدِ: ذَلِكَ (указательное слово «тот»)', '<b>ذَلِكَ</b> относится к одному удалённому предмету или лицу мужского рода.<br><br><ul><li><b>ذَلِكَ مَسْجِدٌ.</b> — То — мечеть.</li><li><b>مَا ذَلِكَ؟ ذَلِكَ حَجَرٌ.</b> — Что то? То — камень.</li></ul><br><br><b>Примечание.</b> В <b>ذَلِكَ</b> алиф после <b>ذَ</b> произносится, но отдельной буквой не пишется.', 1, 'rule', 'ذَلِكَ относится к одному удалённому предмету или лицу мужского рода. ذَلِكَ مَسْجِدٌ. — То — мечеть. مَا ذَلِكَ؟ ذَلِكَ حَجَرٌ. — Что то? То — камень. Примечание. В ذَلِكَ алиф после ذَ произносится, но отдельной буквой не пишется.'),
('Мединский курс (Том 1)', '2', 'حَرْفُ الْعَطْفِ: وَ (союз «и»)', '<b>وَ</b> присоединяется к следующему слову без пробела в арабской записи.<br><br><ul><li><b>هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ.</b> — Это дом, а то мечеть.</li><li><b>هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ.</b> — Это сахар, а то молоко.</li></ul><br><br><b>Дополнительное объяснение:</b> <b>وَ</b> — союз <b>حَرْفُ عَطْفٍ</b>; в русском переводе по смыслу возможны «и» или «а».', 2, 'rule', 'وَ присоединяется к следующему слову без пробела в арабской записи. هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ. — Это дом, а то мечеть. هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ. — Это сахар, а то молоко. Дополнительное объяснение: وَ — союз حَرْفُ عَطْفٍ ; в русс'),
('Мединский курс (Том 1)', '3', 'أَدَاةُ التَّعْرِيفِ: أَلْـ (определённый артикль)', 'Артикль <b>أَلْـ</b> делает существительное определённым: <b>بَيْتٌ</b> — «какой-то дом», <b>الْبَيْتُ</b> — «этот/известный дом». При присоединении артикля танвин исчезает.<br><br><ul><li><b>هَذَا بَيْتٌ. الْبَيْتُ جَدِيدٌ.</b> — Это дом. Дом новый.</li><li><b>الْبَابُ مَفْتُوحٌ.</b> — Дверь открыта.</li></ul>', 1, 'rule', 'Артикль أَلْـ делает существительное определённым: بَيْتٌ — «какой-то дом», الْبَيْتُ — «этот/известный дом». При присоединении артикля танвин исчезает. هَذَا بَيْتٌ. الْبَيْتُ جَدِيدٌ. — Это дом. Дом новый. الْبَابُ مَفْتُوحٌ. — Дверь откр'),
('Мединский курс (Том 1)', '3', 'الْحُرُوفُ الْقَمَرِيَّةُ وَالشَّمْسِيَّةُ (лунные и солнечные буквы)', 'Перед лунной буквой <b>لْ</b> артикля произносится: <b>الْقَمَرُ، الْبَيْتُ</b>. Перед солнечной буквой звук <b>لْ</b> не произносится, а следующая буква удваивается: <b>الشَّمْسُ، الرَّجُلُ، الطَّالِبُ</b>.<br><br>Солнечные буквы: <b>ت، ث، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ل، ن</b>. Остальные — лунные.<br><br><b>Дополнительное объяснение.</b> Написание <b>ل</b> сохраняется в обоих случаях; меняется произношение. Удвоение солнечной буквы обозначается <b>شَدَّةٌ</b>.', 2, 'rule', 'Перед лунной буквой لْ артикля произносится: الْقَمَرُ، الْبَيْتُ . Перед солнечной буквой звук لْ не произносится, а следующая буква удваивается: الشَّمْسُ، الرَّجُلُ، الطَّالِبُ . Солнечные буквы: ت، ث، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ل، ن '),
('Мединский курс (Том 1)', '3', 'هَمْزَةُ الْوَصْلِ فِي أَلْـ (соединительная хамза артикля)', 'В начале речи артикль произносится с гласным: <b>اَلْبَيْتُ</b>. После предыдущего слова начальный гласный опускается: <b>بَابُ الْبَيْتِ</b>. Это явление называется <b>هَمْزَةُ الْوَصْلِ</b>.', 3, 'rule', 'В начале речи артикль произносится с гласным: اَلْبَيْتُ . После предыдущего слова начальный гласный опускается: بَابُ الْبَيْتِ . Это явление называется هَمْزَةُ الْوَصْلِ .'),
('Мединский курс (Том 1)', '4', 'حُرُوفُ الْجَرِّ (предлоги и родительный падеж)', '<div class="rule-note"><b>Внутренняя структура:</b> части 4 и 4A.</div><br><br>В уроке вводятся <b>فِي</b> — в, <b>عَلَى</b> — на, а во второй части <b>مِنْ</b> — из/от и <b>إِلَى</b> — к/в. Существительное после предлога ставится в родительный падеж <b>مَجْرُورٌ</b> и обычно получает <b>ـِ</b> или <b>ـٍ</b>.<br><br><ul><li><b>الْكِتَابُ عَلَى الْمَكْتَبِ.</b> — Книга на столе.</li><li><b>بِلَالٌ فِي الْمَسْجِدِ.</b> — Биляль в мечети.</li><li><b>أَنَا مِنَ الْيَابَانِ.</b> — Я из Японии.</li><li><b>ذَهَبَ الطَّالِبُ إِلَى الْجَامِعَةِ.</b> — Студент пошёл в университет.</li></ul><br><br><b>Дополнительное объяснение:</b> предложное сочетание может быть частью сообщения о предмете: <b>الْكِتَابُ عَلَى الْمَكْتَبِ</b>. Конечная <b>ـُ</b> у существительного сменяется на <b>ـِ</b> после предлога.', 1, 'rule', 'Внутренняя структура: части 4 и 4A. В уроке вводятся فِي — в, عَلَى — на, а во второй части مِنْ — из/от и إِلَى — к/в. Существительное после предлога ставится в родительный падеж مَجْرُورٌ и обычно получает ـِ или ـٍ . الْكِتَابُ عَلَى الْ'),
('Мединский курс (Том 1)', '4', 'أَيْنَ؟ (вопрос «где?»)', '<ul><li><b>أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ.</b> — Где книга? Она на столе.</li><li><b>أَيْنَ آمِنَةُ؟ هِيَ فِي الْبَيْتِ.</b> — Где Амина? Она дома.</li></ul>', 2, 'rule', 'أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ. — Где книга? Она на столе. أَيْنَ آمِنَةُ؟ هِيَ فِي الْبَيْتِ. — Где Амина? Она дома.'),
('Мединский курс (Том 1)', '4', 'ضَمِيرَا الْغَائِبِ: هُوَ وَهِيَ (местоимения «он/оно» и «она»)', '<b>هُوَ</b> заменяет существительное мужского рода, <b>هِيَ</b> — женского. В арабском грамматический род не всегда совпадает с русским: <b>كِتَابٌ</b> — мужского рода, <b>سَيَّارَةٌ</b> — женского.<br><br><ul><li><b>أَيْنَ الْقَلَمُ؟ هُوَ فِي الْحَقِيبَةِ.</b> — Где ручка? Она в сумке.</li><li><b>أَيْنَ السَّاعَةُ؟ هِيَ عَلَى السَّرِيرِ.</b> — Где часы? Они на кровати.</li></ul>', 3, 'rule', 'هُوَ заменяет существительное мужского рода, هِيَ — женского. В арабском грамматический род не всегда совпадает с русским: كِتَابٌ — мужского рода, سَيَّارَةٌ — женского. أَيْنَ الْقَلَمُ؟ هُوَ فِي الْحَقِيبَةِ. — Где ручка? Она в сумке. أَ'),
('Мединский курс (Том 1)', '4', 'الْمُؤَنَّثُ وَالتَّاءُ الْمَرْبُوطَةُ (женский род и ة)', 'Большинство слов с <b>ة</b> относятся к женскому роду: <b>سَيَّارَةٌ، غُرْفَةٌ</b>. Но женский род может быть и без <b>ة</b>, а наличие <b>ة</b> не является единственным возможным признаком.', 4, 'rule', 'Большинство слов с ة относятся к женскому роду: سَيَّارَةٌ، غُرْفَةٌ . Но женский род может быть и без ة , а наличие ة не является единственным возможным признаком.'),
('Мединский курс (Том 1)', '4', 'ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَنَا وَأَنْتَ (местоимения «я» и «ты» к мужчине)', '<ul><li><b>أَنَا مُحَمَّدٌ.</b> — Я Мухаммад.</li><li><b>أَنْتَ طَالِبٌ.</b> — Ты студент.</li></ul>', 5, 'rule', 'أَنَا مُحَمَّدٌ. — Я Мухаммад. أَنْتَ طَالِبٌ. — Ты студент.'),
('Мединский курс (Том 1)', '4', 'الْفِعْلُ الْمَاضِي لِلْمُفْرَدِ الْمُذَكَّرِ: ذَهَبَ (прошедшее время, «он пошёл»)', '<b>ذَهَبَ</b> означает «он пошёл». Если названо лицо, отдельное <b>هُوَ</b> не требуется: <b>ذَهَبَ بِلَالٌ</b> — «Биляль пошёл».', 6, 'rule', 'ذَهَبَ означает «он пошёл». Если названо лицо, отдельное هُوَ не требуется: ذَهَبَ بِلَالٌ — «Биляль пошёл».'),
('Мединский курс (Том 1)', '5', 'الْإِضَافَةُ: الْمُضَافُ وَالْمُضَافُ إِلَيْهِ (конструкция принадлежности)', 'В сочетании «книга Биляля» сначала ставится предмет, затем владелец: <b>كِتَابُ بِلَالٍ</b>. Первое слово — <b>مُضَافٌ</b>, второе — <b>مُضَافٌ إِلَيْهِ</b>.<br><br>Правила:<br><br>1. <b>مُضَافٌ</b> не принимает <b>أَلْـ</b> и танвин.<br>2. <b>مُضَافٌ إِلَيْهِ</b> всегда стоит в родительном падеже.<br>3. Вся конструкция определённая, если владелец определён: <b>بَيْتُ الْإِمَامِ</b> — дом имама.<br><br><ul><li><b>هَذَا كِتَابُ الطَّالِبِ.</b> — Это книга студента.</li><li><b>بَابُ الْفَصْلِ مَفْتُوحٌ.</b> — Дверь класса открыта.</li><li><b>مِفْتَاحُ السَّيَّارَةِ عَلَى الْمَكْتَبِ.</b> — Ключ от машины на столе.</li></ul>', 1, 'rule', 'В сочетании «книга Биляля» сначала ставится предмет, затем владелец: كِتَابُ بِلَالٍ . Первое слово — مُضَافٌ , второе — مُضَافٌ إِلَيْهِ . Правила: 1. مُضَافٌ не принимает أَلْـ и танвин. 2. مُضَافٌ إِلَيْهِ всегда стоит в родительном паде'),
('Мединский курс (Том 1)', '5', 'يَا النِّدَاءُ (обращение с يَا)', 'При обращении к одному человеку по имени: <b>يَا بِلَالُ</b>. В учебной модели имя после <b>يَا</b> получает одну дамму, а не танвин.<br><br><ul><li><b>يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟</b> — Мухаммад, где твоя книга?</li></ul>', 2, 'rule', 'При обращении к одному человеку по имени: يَا بِلَالُ . В учебной модели имя после يَا получает одну дамму, а не танвин. يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟ — Мухаммад, где твоя книга?'),
('Мединский курс (Том 1)', '5', 'اِبْنٌ بَيْنَ عَلَمَيْنِ (слово «сын» между двумя именами)', 'Если <b>اِبْنُ</b> находится между именем человека и именем его отца, начальная алиф на письме обычно опускается: <b>مُحَمَّدُ بْنُ عَبْدِ اللهِ</b>. Это отдельное орфографическое правило; не следует превращать его в общую замену слова <b>اِبْنٌ</b>.', 3, 'rule', 'Если اِبْنُ находится между именем человека и именем его отца, начальная алиф на письме обычно опускается: مُحَمَّدُ بْنُ عَبْدِ اللهِ . Это отдельное орфографическое правило; не следует превращать его в общую замену слова اِبْنٌ .'),
('Мединский курс (Том 1)', '6', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْقَرِيبَةِ: هَذِهِ (указательное слово «эта»)', '<ul><li><b>هَذِهِ سَيَّارَةٌ.</b> — Это машина.</li><li><b>مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ.</b> — Что это? Это ложка.</li></ul><br><br>В <b>هَذِهِ</b> алиф после <b>هَاء</b> произносится, но отдельно не пишется. Конечная <b>ـهِ</b> произносится с кратким <b>и</b>.', 1, 'rule', 'هَذِهِ سَيَّارَةٌ. — Это машина. مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ. — Что это? Это ложка. В هَذِهِ алиф после هَاء произносится, но отдельно не пишется. Конечная ـهِ произносится с кратким и .'),
('Мединский курс (Том 1)', '6', 'تَأْنِيثُ الِاسْمِ وَالصِّفَةِ بِالتَّاءِ الْمَرْبُوطَةِ (образование женского рода)', 'Часто женская форма образуется добавлением <b>ة</b>: <b>مُدَرِّسٌ ← مُدَرِّسَةٌ</b>, <b>جَدِيدٌ ← جَدِيدَةٌ</b>.<br><br><ul><li><b>هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِيرَةٌ.</b> — Это маленький мальчик, а это маленькая девочка.</li></ul><br><br>Не каждое слово образует женский род механически; формы нужно сверять со словарём.', 2, 'rule', 'Часто женская форма образуется добавлением ة : مُدَرِّسٌ ← مُدَرِّسَةٌ , جَدِيدٌ ← جَدِيدَةٌ . هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِيرَةٌ. — Это маленький мальчик, а это маленькая девочка. Не каждое слово образует женский род механичес'),
('Мединский курс (Том 1)', '6', 'أَسْمَاءُ أَعْضَاءِ الْجِسْمِ الْمُزْدَوِجَةِ (названия парных частей тела)', 'В учебнике отмечается, что многие названия парных частей тела женского рода: <b>يَدٌ، رِجْلٌ، عَيْنٌ، أُذُنٌ</b>. Это полезное наблюдение, но не универсальный закон для любого «парного предмета».', 3, 'rule', 'В учебнике отмечается, что многие названия парных частей тела женского рода: يَدٌ، رِجْلٌ، عَيْنٌ، أُذُنٌ . Это полезное наблюдение, но не универсальный закон для любого «парного предмета».'),
('Мединский курс (Том 1)', '6', 'لِـ، لِمَنْ؟ (принадлежность с предлогом لِـ)', '<b>لِـ</b> означает «принадлежит/для». После него существительное в родительном падеже.<br><br><ul><li><b>الْكِتَابُ لِبِلَالٍ.</b> — Книга принадлежит Билялю.</li><li><b>لِمَنْ هَذَا الْقَلَمُ؟ هُوَ لِلْمُدَرِّسِ.</b> — Чья это ручка? Она принадлежит учителю.</li><li><b>الْحَمْدُ لِلَّهِ.</b> — Хвала Аллаху. В сочетании <b>لِـ + اللهُ</b> начальная алиф опускается: <b>لِلَّهِ</b>.</li></ul>', 4, 'rule', 'لِـ означает «принадлежит/для». После него существительное в родительном падеже. الْكِتَابُ لِبِلَالٍ. — Книга принадлежит Билялю. لِمَنْ هَذَا الْقَلَمُ؟ هُوَ لِلْمُدَرِّسِ. — Чья это ручка? Она принадлежит учителю. الْحَمْدُ لِلَّهِ. — Хв'),
('Мединский курс (Том 1)', '6', 'جِدًّا (наречие «очень»)', '<ul><li><b>هَذَا جَمِيلٌ جِدًّا.</b> — Это очень красиво.</li><li><b>هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا.</b> — Это очень красивая машина.</li></ul>', 5, 'rule', 'هَذَا جَمِيلٌ جِدًّا. — Это очень красиво. هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا. — Это очень красивая машина.'),
('Мединский курс (Том 1)', '7', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْبَعِيدَةِ: تِلْكَ (указательное слово «та»)', '<b>تِلْكَ</b> указывает на один удалённый предмет женского рода.<br><br><ul><li><b>هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ.</b> — Это Амина, а та — Марьям.</li><li><b>مَا تِلْكَ؟ تِلْكَ نَاقَةٌ.</b> — Что там? Там верблюдица.</li></ul><br><br><b>Дополнительное объяснение:</b> <b>تِلْكَ</b> — неизменяемое указательное слово; его роль определяется местом в предложении.', 1, 'rule', 'تِلْكَ указывает на один удалённый предмет женского рода. هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ. — Это Амина, а та — Марьям. مَا تِلْكَ؟ تِلْكَ نَاقَةٌ. — Что там? Там верблюдица. Дополнительное объяснение: تِلْكَ — неизменяемое указательное сло'),
('Мединский курс (Том 1)', '8', 'اِسْمُ الْإِشَارَةِ مَعَ الِاسْمِ الْمُعَرَّفِ (указательное слово + определённое существительное)', '<b>هَذَا كِتَابٌ</b> — законченное предложение «Это книга». <b>هَذَا الْكِتَابُ</b> — сочетание «эта книга» и само по себе обычно не является законченным сообщением.<br><br><ul><li><b>هَذَا الْكِتَابُ جَدِيدٌ.</b> — Эта книга новая.</li><li><b>ذَلِكَ الرَّجُلُ مُهَنْدِسٌ.</b> — Тот мужчина — инженер.</li><li><b>هَذِهِ السَّيَّارَةُ جَمِيلَةٌ.</b> — Эта машина красивая.</li></ul><br><br><b>Дополнительное объяснение.</b> Определённое существительное после указательного слова можно разбирать как <b>بَدَلٌ</b> или <b>عَطْفُ بَيَانٍ</b>. В тренажёре достаточно пометить его как поясняющее существительное; нельзя называть всё сочетание обычным «подлежащее + сказуемое».', 1, 'rule', 'هَذَا كِتَابٌ — законченное предложение «Это книга». هَذَا الْكِتَابُ — сочетание «эта книга» и само по себе обычно не является законченным сообщением. هَذَا الْكِتَابُ جَدِيدٌ. — Эта книга новая. ذَلِكَ الرَّجُلُ مُهَنْدِسٌ. — Тот мужчина '),
('Мединский курс (Том 1)', '8', 'الِاسْمُ الْمَقْصُورُ وَالْحَرَكَاتُ الْمُقَدَّرَةُ (слова на алиф и скрытые окончания)', 'У слов, заканчивающихся на долгий <b>ا/ى</b>, конечная падежная огласовка может быть непроизносимой и считается предполагаемой: <b>الْمُسْتَشْفَى، مُوسَى</b>.<br><br><ul><li><b>هُوَ فِي الْمُسْتَشْفَى.</b> — Он в больнице.</li></ul><br><br>Важно: это не означает, что все такие слова неизменяемы. <b>الْمُسْتَشْفَى</b> — склоняемое слово с предполагаемой касрой после <b>فِي</b>; <b>مُوسَى</b> и <b>أَمْرِيكَا</b> относятся также к несклоняемым по танвину словам и в родительном падеже имеют предполагаемую фатху, если нет <b>أَلْـ</b> и идафы.', 2, 'rule', 'У слов, заканчивающихся на долгий ا/ى , конечная падежная огласовка может быть непроизносимой и считается предполагаемой: الْمُسْتَشْفَى، مُوسَى . هُوَ فِي الْمُسْتَشْفَى. — Он в больнице. Важно: это не означает, что все такие слова неизмен'),
('Мединский курс (Том 1)', '8', 'أَمَامَ وَخَلْفَ (обстоятельства места «перед» и «за»)', '<ul><li><b>حَامِدٌ أَمَامَ الْمُدَرِّسِ.</b> — Хамид перед учителем.</li><li><b>الْبَيْتُ خَلْفَ الْمَسْجِدِ.</b> — Дом за мечетью.</li></ul><br><br><b>أَمَامَ</b> и <b>خَلْفَ</b> обычно выступают первым членом идафы; следующее существительное стоит в родительном падеже.', 3, 'rule', 'حَامِدٌ أَمَامَ الْمُدَرِّسِ. — Хамид перед учителем. الْبَيْتُ خَلْفَ الْمَسْجِدِ. — Дом за мечетью. أَمَامَ и خَلْفَ обычно выступают первым членом идафы; следующее существительное стоит в родительном падеже.'),
('Мединский курс (Том 1)', '9', 'النَّعْتُ وَالْمَنْعُوتُ (прилагательное и определяемое слово)', '<div class="rule-note"><b>Внутренняя структура:</b> части A и B.</div><br><br>В арабском прилагательное стоит после существительного и согласуется с ним в роде, определённости и падеже; позднее добавится согласование в числе.<br><br><ul><li><b>بَيْتٌ جَدِيدٌ.</b> — Новый дом. Оба слова неопределённые и именительные.</li><li><b>سَيَّارَةٌ جَدِيدَةٌ.</b> — Новая машина. Прилагательное женского рода.</li><li><b>الْمُدَرِّسُ الْجَدِيدُ فِي الْفَصْلِ.</b> — Новый учитель в классе. Оба слова определённые.</li><li><b>أَنَا فِي بَيْتٍ جَدِيدٍ.</b> — Я в новом доме. Оба слова родительного падежа после <b>فِي</b>.</li></ul><br><br><b>Дополнительное объяснение.</b> Существительное — <b>مَنْعُوتٌ</b>, прилагательное — <b>نَعْتٌ</b>. Несогласованность хотя бы по одному признаку меняет структуру или делает фразу ошибочной.', 1, 'rule', 'Внутренняя структура: части A и B. В арабском прилагательное стоит после существительного и согласуется с ним в роде, определённости и падеже; позднее добавится согласование в числе. بَيْتٌ جَدِيدٌ. — Новый дом. Оба слова неопределённые и и'),
('Мединский курс (Том 1)', '9', 'الصِّفَاتُ الْمُخْتُومَةُ بِـ«ـَانُ» (прилагательные на ـَانُ)', 'Некоторые прилагательные на <b>ـَانُ</b> не принимают танвин: <b>عَطْشَانُ، جَوْعَانُ، غَضْبَانُ، مَلْآنُ</b>. Их женские формы изучаются как словарные.', 2, 'rule', 'Некоторые прилагательные на ـَانُ не принимают танвин: عَطْشَانُ، جَوْعَانُ، غَضْبَانُ، مَلْآنُ . Их женские формы изучаются как словарные.'),
('Мединский курс (Том 1)', '9', 'الِاسْمُ الْمَوْصُولُ: الَّذِي (относительное слово «который»)', '<b>الَّذِي</b> относится к одному слову мужского рода и вводит придаточное описание.<br><br><ul><li><b>الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ.</b> — Мужчина, который вышел из мечети, — торговец.</li><li><b>الْبَيْتُ الَّذِي أَمَامَ الْمَسْجِدِ لِلْإِمَامِ.</b> — Дом, который перед мечетью, принадлежит имаму.</li></ul>', 3, 'rule', 'الَّذِي относится к одному слову мужского рода и вводит придаточное описание. الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ. — Мужчина, который вышел из мечети, — торговец. الْبَيْتُ الَّذِي أَمَامَ الْمَسْجِدِ لِلْإِمَامِ. — Дом, котор'),
('Мединский курс (Том 1)', '9', 'عِنْدَ (значения «у/при/рядом с»)', '<ul><li><b>الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</b> — Учитель у директора, то есть находится у него.</li></ul><br><br>Следующее существительное стоит в родительном падеже: <b>عِنْدَ الْمُدِيرِ</b>.', 4, 'rule', 'الْمُدَرِّسُ عِنْدَ الْمُدِيرِ. — Учитель у директора, то есть находится у него. Следующее существительное стоит в родительном падеже: عِنْدَ الْمُدِيرِ .'),
('Мединский курс (Том 1)', '9', 'لِـ مَعَ أَلْـ (слияние предлога لِـ с артиклем)', 'При соединении <b>لِـ</b> с существительным на <b>أَلْـ</b> алиф артикля опускается: <b>لِـ + الْإِمَامِ = لِلْإِمَامِ</b>.', 5, 'rule', 'При соединении لِـ с существительным на أَلْـ алиф артикля опускается: لِـ + الْإِمَامِ = لِلْإِمَامِ .'),
('Мединский курс (Том 1)', '10', 'ضَمَائِرُ الْمِلْكِيَّةِ الْمُتَّصِلَةُ (притяжательные суффиксы)', 'Вводятся <b>ـِي</b> — мой, <b>ـكَ</b> — твой (к мужчине), <b>ـهُ</b> — его, <b>ـهَا</b> — её. Это не самостоятельные слова, а присоединяемые местоимения.<br><br><ul><li><b>كِتَابِي</b> — моя книга.</li><li><b>كِتَابُكَ</b> — твоя книга.</li><li><b>كِتَابُهُ</b> — его книга.</li><li><b>كِتَابُهَا</b> — её книга.</li></ul><br><br><h4>Пример с и‘раб-разметкой (включается с урока 10)</h4><br><br><div class="iarab-example" dir="rtl"><br><br><span class="iarab-token role-mubtada"><span class="iarab-word">كِتَابُكَ</span><span class="iarab-label">مُبْتَدَأٌ مَرْفُوعٌ</span></span><br><br><span class="iarab-token role-khabar"><span class="iarab-word">جَدِيدٌ</span><span class="iarab-label">خَبَرٌ مَرْفُوعٌ</span></span><br><br></div><br><br><b>كِتَابُكَ جَدِيدٌ.</b> — Твоя книга новая. Первое слово — мубтада; второе — хабар. Суффикс <b>ـكَ</b> внутри <b>كِتَابُكَ</b> — <b>ضَمِيرٌ مُتَّصِلٌ فِي مَحَلِّ جَرٍّ</b> и выполняет роль второго члена идафы.<br><br>При присоединении суффикса танвин и артикль у существительного не употребляются. Суффикс делает сочетание определённым.', 1, 'rule', 'Вводятся ـِي — мой, ـكَ — твой (к мужчине), ـهُ — его, ـهَا — её. Это не самостоятельные слова, а присоединяемые местоимения. كِتَابِي — моя книга. كِتَابُكَ — твоя книга. كِتَابُهُ — его книга. كِتَابُهَا — её книга. Пример с и‘раб-разметк'),
('Мединский курс (Том 1)', '10', 'أَبٌ وَأَخٌ فِي الْإِضَافَةِ (слова «отец» и «брат» в идафе)', 'В именительном падеже перед не-йа-суффиксом формы <b>أَبٌ</b> и <b>أَخٌ</b> получают <b>و</b>: <b>أَبُوكَ، أَخُوهُ، أَبُو مُحَمَّدٍ</b>.<br><br><ul><li><b>أَبُوكَ مُدَرِّسٌ.</b> — Твой отец — учитель.</li><li><b>أَخُوهُ طَبِيبٌ.</b> — Его брат — врач.</li></ul><br><br><b>Дополнительное объяснение.</b> Это часть темы <b>الْأَسْمَاءُ الْخَمْسَةُ</b>. Форма зависит от падежа: именительный <b>أَبُوكَ</b>, винительный <b>أَبَاكَ</b>, родительный <b>أَبِيكَ</b>. Перед <b>يَاءُ الْمُتَكَلِّمِ</b>: <b>أَبِي، أَخِي</b>. Нельзя учить правило как «всегда добавляется و».', 2, 'rule', 'В именительном падеже перед не-йа-суффиксом формы أَبٌ и أَخٌ получают و : أَبُوكَ، أَخُوهُ، أَبُو مُحَمَّدٍ . أَبُوكَ مُدَرِّسٌ. — Твой отец — учитель. أَخُوهُ طَبِيبٌ. — Его брат — врач. Дополнительное объяснение. Это часть темы الْأَسْمَ'),
('Мединский курс (Том 1)', '10', 'عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْكِ (конструкция «у меня есть»)', '<ul><li><b>عِنْدِي قَلَمٌ.</b> — У меня есть ручка.</li><li><b>أَعِنْدَكَ سَيَّارَةٌ؟</b> — У тебя есть машина?</li></ul><br><br>Буквально это местная конструкция «при мне/при тебе находится…».', 3, 'rule', 'عِنْدِي قَلَمٌ. — У меня есть ручка. أَعِنْدَكَ سَيَّارَةٌ؟ — У тебя есть машина? Буквально это местная конструкция «при мне/при тебе находится…».'),
('Мединский курс (Том 1)', '10', 'لِـ مَعَ الضَّمَائِرِ (предлог لِـ с местоимениями)', 'Формы: <b>لِي، لَكَ، لَهُ، لَهَا</b>.<br><br><ul><li><b>لِي أَخٌ.</b> — У меня есть брат.</li><li><b>الْكِتَابُ لَهُ.</b> — Книга принадлежит ему.</li></ul>', 4, 'rule', 'Формы: لِي، لَكَ، لَهُ، لَهَا . لِي أَخٌ. — У меня есть брат. الْكِتَابُ لَهُ. — Книга принадлежит ему.'),
('Мединский курс (Том 1)', '10', 'ذَهَبْتَ وَذَهَبْتُ (прошедшее «ты пошёл» и «я пошёл»)', '<ul><li><b>أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ.</b> — Куда ты ходил? Я ходил в школу.</li></ul><br><br><div class="iarab-example" dir="rtl"><br><br><span class="iarab-token role-fiil"><span class="iarab-word">ذَهَبَ</span><span class="iarab-label">فِعْلٌ مَاضٍ</span></span><br><br><span class="iarab-token role-fail"><span class="iarab-word">الطَّالِبُ</span><span class="iarab-label">فَاعِلٌ مَرْفُوعٌ</span></span><br><br><span class="iarab-token role-harf"><span class="iarab-word">إِلَى</span><span class="iarab-label">حَرْفُ جَرٍّ</span></span><br><br><span class="iarab-token role-majrur"><span class="iarab-word">الْمَدْرَسَةِ</span><span class="iarab-label">اِسْمٌ مَجْرُورٌ</span></span><br><br></div><br><br><b>ذَهَبَ الطَّالِبُ إِلَى الْمَدْرَسَةِ.</b> — Студент пошёл в школу. Глагол сообщает действие; <b>الطَّالِبُ</b> — кто совершил действие; после <b>إِلَى</b> слово получает родительный падеж.<br><br><b>ذَهَبْتَ</b> — ты, мужчина; <b>ذَهَبْتُ</b> — я. Окончание одновременно показывает лицо, поэтому отдельное местоимение обычно не требуется.', 5, 'rule', 'أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ. — Куда ты ходил? Я ходил в школу. ذَهَبَ فِعْلٌ مَاضٍ الطَّالِبُ فَاعِلٌ مَرْفُوعٌ إِلَى حَرْفُ جَرٍّ الْمَدْرَسَةِ اِسْمٌ مَجْرُورٌ ذَهَبَ الطَّالِبُ إِلَى الْمَدْرَسَةِ. — Студент пошёл в шко'),
('Мединский курс (Том 1)', '10', 'مَعَ وَعِنْدَ (различие «вместе с» и «у»)', '<b>مَعَ</b> обозначает совместность без привязки к месту, <b>عِنْدَ</b> — нахождение у кого-либо или рядом с ним.<br><br><ul><li><b>الْمُدَرِّسُ مَعَ الْمُدِيرِ.</b> — Учитель вместе с директором.</li><li><b>الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</b> — Учитель у директора.</li></ul>', 6, 'rule', 'مَعَ обозначает совместность без привязки к месту, عِنْدَ — нахождение у кого-либо или рядом с ним. الْمُدَرِّسُ مَعَ الْمُدِيرِ. — Учитель вместе с директором. الْمُدَرِّسُ عِنْدَ الْمُدِيرِ. — Учитель у директора.'),
('Мединский курс (Том 1)', '10', 'مَا النَّافِيَةُ (отрицательная مَا)', '<ul><li><b>مَا عِنْدِي سَيَّارَةٌ.</b> — У меня нет машины.</li></ul><br><br>Здесь <b>مَا</b> не означает «что?», а отрицает сообщение. Значение определяется контекстом и отсутствием вопросительной конструкции.', 7, 'rule', 'مَا عِنْدِي سَيَّارَةٌ. — У меня нет машины. Здесь مَا не означает «что?», а отрицает сообщение. Значение определяется контекстом и отсутствием вопросительной конструкции.'),
('Мединский курс (Том 1)', '11', 'فِيهِ وَفِيهَا (предлог فِي с местоименными суффиксами)', 'Автор прямо называет этот урок повторительным; новых конструкций мало.<br><br><b>فِيهِ</b> — в нём/там (для мужского рода), <b>فِيهَا</b> — в ней/там (для женского рода).<br><br><ul><li><b>مَنْ فِي الْبَيْتِ؟ فِيهِ أَبِي وَأُمِّي.</b> — Кто в доме? В нём мои отец и мать.</li><li><b>مَنْ فِي الْغُرْفَةِ؟ فِيهَا أَخِي.</b> — Кто в комнате? В ней мой брат.</li></ul>', 1, 'rule', 'Автор прямо называет этот урок повторительным; новых конструкций мало. فِيهِ — в нём/там (для мужского рода), فِيهَا — в ней/там (для женского рода). مَنْ فِي الْبَيْتِ؟ فِيهِ أَبِي وَأُمِّي. — Кто в доме? В нём мои отец и мать. مَنْ فِي ال'),
('Мединский курс (Том 1)', '11', 'الْمَفْعُولُ بِهِ (прямое дополнение)', 'После переходного глагола объект ставится в винительном падеже <b>مَنْصُوبٌ</b>.<br><br><ul><li><b>أُحِبُّ اللهَ.</b> — Я люблю Аллаха.</li><li><b>أُحِبُّ الرَّسُولَ.</b> — Я люблю Посланника.</li><li><b>أُحِبُّ اللُّغَةَ الْعَرَبِيَّةَ.</b> — Я люблю арабский язык.</li></ul><br><br><b>Дополнительное объяснение.</b> В единственном числе обычным признаком винительного падежа является фатха, но не всякое дополнение во всех формах помечается именно фатхой. Правильно говорить: «дополнение стоит в винительном падеже», а не «всегда заканчивается на фатху».', 2, 'rule', 'После переходного глагола объект ставится в винительном падеже مَنْصُوبٌ . أُحِبُّ اللهَ. — Я люблю Аллаха. أُحِبُّ الرَّسُولَ. — Я люблю Посланника. أُحِبُّ اللُّغَةَ الْعَرَبِيَّةَ. — Я люблю арабский язык. Дополнительное объяснение. В ед'),
('Мединский курс (Том 1)', '11', 'أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟ (глаголы «люблю/любишь», вопросы к объекту)', '<ul><li><b>أَتُحِبُّ لُغَتَكَ؟</b> — Ты любишь свой язык?</li><li><b>مَنْ تُحِبُّ؟</b> — Кого ты любишь?</li><li><b>مَاذَا تُحِبُّ؟</b> — Что ты любишь?</li></ul>', 3, 'rule', 'أَتُحِبُّ لُغَتَكَ؟ — Ты любишь свой язык? مَنْ تُحِبُّ؟ — Кого ты любишь? مَاذَا تُحِبُّ؟ — Что ты любишь?'),
('Мединский курс (Том 1)', '12', 'أَنْتِ وَـكِ (женское «ты» и «твой»)', '<b>أَنْتِ</b> обращено к одной женщине; соответствующий притяжательный суффикс — <b>ـكِ</b>.<br><br><ul><li><b>مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟</b> — Откуда ты, Амина?</li><li><b>أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟</b> — Где твой дом, Марьям?</li></ul>', 1, 'rule', 'أَنْتِ обращено к одной женщине; соответствующий притяжательный суффикс — ـكِ . مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟ — Откуда ты, Амина? أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟ — Где твой дом, Марьям?'),
('Мединский курс (Том 1)', '12', 'ذَهَبَتْ (форма «она пошла»)', '<ul><li><b>ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ.</b> — Амина пошла в университет.</li></ul><br><br>Если подлежащее названо, <b>هِيَ</b> опускается. В форме <b>ذَهَبَتْ</b> конечная <b>تْ</b> имеет сукун. Перед словом с соединительной хамзой для удобства произношения возникает касра: <b>ذَهَبَتِ الْبِنْتُ</b>.', 2, 'rule', 'ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ. — Амина пошла в университет. Если подлежащее названо, هِيَ опускается. В форме ذَهَبَتْ конечная تْ имеет сукун. Перед словом с соединительной хамзой для удобства произношения возникает касра: ذَهَبَتِ ا'),
('Мединский курс (Том 1)', '12', 'الِاسْمُ الْمَوْصُولُ: الَّتِي (относительное слово «которая»)', '<ul><li><b>الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا.</b> — Студентка, которая сидела перед преподавательницей, из Германии.</li></ul>', 3, 'rule', 'الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا. — Студентка, которая сидела перед преподавательницей, из Германии.'),
('Мединский курс (Том 1)', '12', 'ضَمِيرُ الْفَصْلِ لِلتَّوْكِيدِ فِي نَمَطِ الدَّرْسِ (личное местоимение для подчёркивания)', '<ul><li><b>هَذَا كِتَابُكَ أَنْتَ.</b> — Это именно твоя книга.</li><li><b>هَذَا بَيْتُهُ هُوَ.</b> — Это именно его дом.</li><li><b>تِلْكَ كِتَابُهَا هِيَ.</b> — Та книга именно её.</li></ul><br><br>Здесь конечное отдельное местоимение добавляет подчёркивание или снимает сомнение.', 4, 'rule', 'هَذَا كِتَابُكَ أَنْتَ. — Это именно твоя книга. هَذَا بَيْتُهُ هُوَ. — Это именно его дом. تِلْكَ كِتَابُهَا هِيَ. — Та книга именно её. Здесь конечное отдельное местоимение добавляет подчёркивание или снимает сомнение.'),
('Мединский курс (Том 1)', '13', 'الْجَمْعُ السَّالِمُ وَجَمْعُ التَّكْسِيرِ (правильное и ломаное множественное число)', '<div class="rule-note"><b>Внутренняя структура:</b> части A, B и C.</div><br><br>В правильном множественном основа сохраняется; в ломаном изменяется внутренняя структура слова.<br><br><ul><li><b>مُسْلِمٌ ← مُسْلِمُونَ</b> — мусульманин → мусульмане.</li><li><b>مُسْلِمَةٌ ← مُسْلِمَاتٌ</b> — мусульманка → мусульманки.</li><li><b>كِتَابٌ ← كُتُبٌ</b> — книга → книги.</li><li><b>رَجُلٌ ← رِجَالٌ</b> — мужчина → мужчины.</li></ul><br><br>В этом уроке мужское правильное множественное вводится в именительной форме <b>ـُونَ</b>. Женское правильное множественное: заменить <b>ة</b> на <b>اتٌ</b>.', 1, 'rule', 'Внутренняя структура: части A, B и C. В правильном множественном основа сохраняется; в ломаном изменяется внутренняя структура слова. مُسْلِمٌ ← مُسْلِمُونَ — мусульманин → мусульмане. مُسْلِمَةٌ ← مُسْلِمَاتٌ — мусульманка → мусульманки. ك'),
('Мединский курс (Том 1)', '13', 'الْمُبْتَدَأُ (первый член именного предложения)', '<b>Суть правила.</b> <b>الْمُبْتَدَأُ</b> — слово, о котором сообщается в именном предложении. В упражнениях этого урока оно изменяется из единственного числа во множественное.<br><br><ul><li><b>هَذَا طَالِبٌ. → هَؤُلَاءِ طُلَّابٌ.</b> — Это студент. → Это студенты. Меняется мубтада; форма сообщения также согласуется с ним.</li></ul><br><br><b>Дополнительное объяснение.</b> В простом именном предложении мубтада обычно стоит в начале и имеет именительный падеж. На этом этапе достаточно узнавать его как главный предмет сообщения; термин «хабар» будет введён в уроке 17.', 2, 'rule', 'Суть правила. الْمُبْتَدَأُ — слово, о котором сообщается в именном предложении. В упражнениях этого урока оно изменяется из единственного числа во множественное. هَذَا طَالِبٌ. → هَؤُلَاءِ طُلَّابٌ. — Это студент. → Это студенты. Меняется '),
('Мединский курс (Том 1)', '13', 'هَؤُلَاءِ (указательное слово «эти» для людей)', '<b>هَؤُلَاءِ</b> употребляется для близкой группы людей обоих родов.<br><br><ul><li><b>هَؤُلَاءِ طُلَّابٌ.</b> — Эти люди — студенты.</li><li><b>هَؤُلَاءِ مُدَرِّسَاتٌ.</b> — Эти женщины — преподавательницы.</li></ul><br><br>В рамках первого тома не следует преждевременно применять <b>هَؤُلَاءِ</b> к обычным неодушевлённым множественным: их согласование вводится в уроке 16.', 3, 'rule', 'هَؤُلَاءِ употребляется для близкой группы людей обоих родов. هَؤُلَاءِ طُلَّابٌ. — Эти люди — студенты. هَؤُلَاءِ مُدَرِّسَاتٌ. — Эти женщины — преподавательницы. В рамках первого тома не следует преждевременно применять هَؤُلَاءِ к обычны'),
('Мединский курс (Том 1)', '13', 'هُمْ، هُنَّ وَضَمَائِرُ الْمِلْكِ (местоимения «они/их»)', '<b>هُمْ</b> — они, мужчины или смешанная группа; <b>هُنَّ</b> — они, женщины. Эти же формы после существительного функционируют как суффиксы <b>ـهُمْ، ـهُنَّ</b> со значением «их».<br><br><ul><li><b>هُمْ إِخْوَتِي.</b> — Они мои братья.</li><li><b>هُنَّ أَخَوَاتِي.</b> — Они мои сёстры.</li><li><b>هَذَا بَيْتُهُمْ.</b> — Это их дом.</li></ul><br><br>В базе нельзя переводить самостоятельное <b>هُمْ</b> просто как «их».', 4, 'rule', 'هُمْ — они, мужчины или смешанная группа; هُنَّ — они, женщины. Эти же формы после существительного функционируют как суффиксы ـهُمْ، ـهُنَّ со значением «их». هُمْ إِخْوَتِي. — Они мои братья. هُنَّ أَخَوَاتِي. — Они мои сёстры. هَذَا بَيْ'),
('Мединский курс (Том 1)', '13', 'ذَهَبُوا وَذَهَبْنَ (прошедшее время, «они пошли»)', '<ul><li><b>ذَهَبُوا إِلَى الْجَامِعَةِ.</b> — Они, мужчины, пошли в университет.</li><li><b>ذَهَبْنَ إِلَى الْمَكْتَبَةِ.</b> — Они, женщины, пошли в библиотеку.</li></ul><br><br>В <b>ذَهَبُوا</b> конечная алиф не произносится; это орфографическая <b>أَلِفُ الْفَارِقَةِ</b> после <b>وَاوُ الْجَمَاعَةِ</b>.', 5, 'rule', 'ذَهَبُوا إِلَى الْجَامِعَةِ. — Они, мужчины, пошли в университет. ذَهَبْنَ إِلَى الْمَكْتَبَةِ. — Они, женщины, пошли в библиотеку. В ذَهَبُوا конечная алиф не произносится; это орфографическая أَلِفُ الْفَارِقَةِ после وَاوُ الْجَمَاعَةِ .'),
('Мединский курс (Том 1)', '13', 'بَعْضُهُمْ (конструкция «некоторые из них»)', '<ul><li><b>بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ.</b> — Некоторые из них учителя, а некоторые инженеры.</li></ul>', 6, 'rule', 'بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ. — Некоторые из них учителя, а некоторые инженеры.'),
('Мединский курс (Том 1)', '13', 'أُولَئِكَ (указательное слово «те» во множественном числе)', '<b>أُولَئِكَ</b> — «те» для людей мужского и женского рода. Буква <b>و</b> в написании не произносится.<br><br><ul><li><b>أُولَئِكَ طُلَّابٌ.</b> — Те люди — студенты.</li><li><b>أُولَئِكَ مُدَرِّسَاتٌ.</b> — Те женщины — преподавательницы.</li></ul>', 7, 'rule', 'أُولَئِكَ — «те» для людей мужского и женского рода. Буква و в написании не произносится. أُولَئِكَ طُلَّابٌ. — Те люди — студенты. أُولَئِكَ مُدَرِّسَاتٌ. — Те женщины — преподавательницы.'),
('Мединский курс (Том 1)', '14', 'أَنْتُمْ وَـكُمْ (множественное «вы/ваш» к мужчинам или смешанной группе)', '<ul><li><b>مَنْ أَنْتُمْ؟</b> — Кто вы?</li><li><b>أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟</b> — Где ваш дом, братья?</li></ul>', 1, 'rule', 'مَنْ أَنْتُمْ؟ — Кто вы? أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟ — Где ваш дом, братья?'),
('Мединский курс (Том 1)', '14', 'نَحْنُ وَـنَا (местоимения «мы/наш»)', '<b>نَحْنُ</b> и суффикс <b>ـنَا</b> употребляются для людей любого пола.<br><br><ul><li><b>نَحْنُ مُسْلِمُونَ.</b> — Мы мусульмане.</li><li><b>نَحْنُ مُسْلِمَاتٌ.</b> — Мы мусульманки.</li><li><b>اللهُ رَبُّنَا.</b> — Аллах — наш Господь.</li></ul>', 2, 'rule', 'نَحْنُ и суффикс ـنَا употребляются для людей любого пола. نَحْنُ مُسْلِمُونَ. — Мы мусульмане. نَحْنُ مُسْلِمَاتٌ. — Мы мусульманки. اللهُ رَبُّنَا. — Аллах — наш Господь.'),
('Мединский курс (Том 1)', '14', 'ذَهَبْتُمْ وَذَهَبْنَا (прошедшее «вы пошли» и «мы пошли»)', '<ul><li><b>أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟</b> — Куда вы пошли, мои сыновья?</li><li><b>ذَهَبْنَا إِلَى الْمَسْجِدِ.</b> — Мы пошли в мечеть.</li></ul><br><br>Не путать <b>ذَهَبْنَا</b> — «мы пошли» и <b>ذَهَبْنَ</b> — «они, женщины, пошли»: долгота <b>ـنَا</b> различает формы.', 3, 'rule', 'أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟ — Куда вы пошли, мои сыновья? ذَهَبْنَا إِلَى الْمَسْجِدِ. — Мы пошли в мечеть. Не путать ذَهَبْنَا — «мы пошли» и ذَهَبْنَ — «они, женщины, пошли»: долгота ـنَا различает формы.'),
('Мединский курс (Том 1)', '14', 'الْعَلَمُ الْأَعْجَمِيُّ الْمَمْنُوعُ مِنَ الصَّرْفِ (иноязычные имена без танвина)', 'Большинство иноязычных собственных имён не принимает танвин: <b>إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ</b>. Мужское трёхбуквенное имя с серединной неподвижной буквой может принимать танвин: <b>نُوحٌ، لُوطٌ</b>.', 4, 'rule', 'Большинство иноязычных собственных имён не принимает танвин: إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ . Мужское трёхбуквенное имя с серединной неподвижной буквой может принимать танвин: نُوحٌ، لُوطٌ .'),
('Мединский курс (Том 1)', '14', 'نَعْتُ الْمُضَافِ الْمَعْرِفَةِ (прилагательное при определённом первом члене идафы)', '<ul><li><b>بَيْتُ الْإِمَامِ الْجَدِيدُ.</b> — Новый дом имама; <b>الْجَدِيدُ</b> описывает <b>بَيْتُ</b>.</li><li><b>بَيْتُ الْإِمَامِ الْجَدِيدِ.</b> — Дом нового имама; <b>الْجَدِيدِ</b> описывает <b>الْإِمَامِ</b>.</li></ul><br><br>Падеж помогает понять, к какому слову относится прилагательное.', 5, 'rule', 'بَيْتُ الْإِمَامِ الْجَدِيدُ. — Новый дом имама; الْجَدِيدُ описывает بَيْتُ . بَيْتُ الْإِمَامِ الْجَدِيدِ. — Дом нового имама; الْجَدِيدِ описывает الْإِمَامِ . Падеж помогает понять, к какому слову относится прилагательное.'),
('Мединский курс (Том 1)', '14', 'أَيُّ (вопросительное «какой/который»)', '<b>أَيُّ</b> всегда является первым членом идафы, поэтому следующее существительное — в родительном падеже. Форма <b>أَيُّ</b> меняется по падежу.<br><br><ul><li><b>أَيُّ بَيْتٍ هَذَا؟</b> — Какой это дом?</li><li><b>أَيُّ طَالِبٍ خَرَجَ؟</b> — Который студент вышел?</li><li><b>مِنْ أَيِّ بَلَدٍ أَنْتَ؟</b> — Из какой ты страны?</li><li><b>فِي أَيِّ فَصْلٍ جَلَسْتَ؟</b> — В каком классе ты сидел?</li></ul>', 6, 'rule', 'أَيُّ всегда является первым членом идафы, поэтому следующее существительное — в родительном падеже. Форма أَيُّ меняется по падежу. أَيُّ بَيْتٍ هَذَا؟ — Какой это дом? أَيُّ طَالِبٍ خَرَجَ؟ — Который студент вышел? مِنْ أَيِّ بَلَدٍ أَنْت'),
('Мединский курс (Том 1)', '15', 'أَنْتُنَّ وَـكُنَّ (женское множественное «вы/ваш»)', '<ul><li><b>مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟</b> — Кто вы, мои сёстры?</li><li><b>أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟</b> — Где ваш дом, дамы?</li></ul>', 1, 'rule', 'مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟ — Кто вы, мои сёстры? أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟ — Где ваш дом, дамы?'),
('Мединский курс (Том 1)', '15', 'ذَهَبْتُنَّ (форма «вы, женщины, пошли»)', '<ul><li><b>أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟</b> — Куда вы пошли, сёстры?</li></ul><br><br>Сравните: <b>ذَهَبْتُمْ</b> — вы, мужчины/смешанная группа; <b>ذَهَبْتُنَّ</b> — вы, женщины.', 2, 'rule', 'أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟ — Куда вы пошли, сёстры? Сравните: ذَهَبْتُمْ — вы, мужчины/смешанная группа; ذَهَبْتُنَّ — вы, женщины.'),
('Мединский курс (Том 1)', '15', 'قَبْلَ وَبَعْدَ (слова «до» и «после»)', 'В модели урока они являются первым членом идафы; следующее слово ставится в родительном падеже.<br><br><ul><li><b>بَعْدَ الدَّرْسِ</b> — после урока.</li><li><b>قَبْلَ الصَّلَاةِ</b> — до молитвы.</li></ul>', 3, 'rule', 'В модели урока они являются первым членом идафы; следующее слово ставится в родительном падеже. بَعْدَ الدَّرْسِ — после урока. قَبْلَ الصَّلَاةِ — до молитвы.'),
('Мединский курс (Том 1)', '15', 'رَجَعَ (глагол «вернулся»)', '<ul><li><b>أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟</b> — Имам вернулся из мечети?</li><li><b>ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ.</b> — Я пошёл в мечеть до азана и вернулся после молитвы.</li></ul>', 4, 'rule', 'أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟ — Имам вернулся из мечети? ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ. — Я пошёл в мечеть до азана и вернулся после молитвы.'),
('Мединский курс (Том 1)', '16', 'جَمْعُ غَيْرِ الْعَاقِلِ يُعَامَلُ مُعَامَلَةَ الْمُفْرَدَةِ الْمُؤَنَّثَةِ (неразумное множественное согласуется как женское единственное)', 'Множественное число слов, обозначающих людей, согласуется как множественное: <b>هَؤُلَاءِ طُلَّابٌ جُدُدٌ. هُمْ صِغَارٌ.</b> Множественное число предметов, животных и отвлечённых понятий в основной учебной модели согласуется как женское единственное.<br><br><ul><li><b>هَذِهِ كُتُبٌ جَدِيدَةٌ. هِيَ صَغِيرَةٌ.</b> — Это новые книги. Они маленькие.</li><li><b>هَذِهِ كِلَابٌ. خَرَجَتْ.</b> — Это собаки. Они вышли.</li></ul><br><br><b>Суть правила:</b> несмотря на русский перевод «они», в арабском употребляются <b>هَذِهِ، هِيَ</b>, женское прилагательное и глагол женского единственного числа.<br><br><b>Дополнительное объяснение.</b> Термины: люди — <b>عَاقِلٌ</b>, неодушевлённое/неразумное — <b>غَيْرُ عَاقِلٍ</b>. В учебнике правило даётся как базовое; стилистические и контекстные исключения изучаются позже.', 1, 'rule', 'Множественное число слов, обозначающих людей, согласуется как множественное: هَؤُلَاءِ طُلَّابٌ جُدُدٌ. هُمْ صِغَارٌ. Множественное число предметов, животных и отвлечённых понятий в основной учебной модели согласуется как женское единственн'),
('Мединский курс (Том 1)', '16', 'صِيغَةُ مُنْتَهَى الْجُمُوعِ: مَفَاعِلُ (ломаное множественное без танвина)', 'Вводится модель <b>مَفَاعِلُ</b>: <b>مَسْجِدٌ ← مَسَاجِدُ</b>, <b>دَفْتَرٌ ← دَفَاتِرُ</b>. Такие формы не принимают танвин. Их полное падежное поведение систематизируется в уроках 22–23.', 2, 'rule', 'Вводится модель مَفَاعِلُ : مَسْجِدٌ ← مَسَاجِدُ , دَفْتَرٌ ← دَفَاتِرُ . Такие формы не принимают танвин. Их полное падежное поведение систематизируется в уроках 22–23.'),
('Мединский курс (Том 1)', '17', 'الْمُبْتَدَأُ وَالْخَبَرُ (мубтада и хабар)', 'Это продолжение урока 16. Авторский ключ прямо указывает: новых конструкций нет.<br><br><b>Суть правила.</b> <b>الْمُبْتَدَأُ</b> — то, о чём говорится; <b>الْخَبَرُ</b> — сообщение о нём. В простой именной фразе оба обычно стоят в именительном падеже.<br><br><ul><li><b>الْبَيْتُ كَبِيرٌ.</b> — Дом большой. <b>الْبَيْتُ</b> — мубтада, <b>كَبِيرٌ</b> — хабар.</li><li><b>النُّجُومُ جَمِيلَةٌ.</b> — Звёзды красивые. <b>النُّجُومُ</b> — мубтада, <b>جَمِيلَةٌ</b> — хабар; при неразумном множественном числе хабар имеет форму женского единственного числа.</li><li><b>فِي الْهِنْدِ لُغَاتٌ كَثِيرَةٌ.</b> — В Индии много языков. Предложная группа стоит впереди, а <b>لُغَاتٌ</b> является сообщаемым словом.</li></ul><br><br><b>Дополнительное объяснение.</b> В упражнениях урока 17 отдельно предлагается «вписать хабар». Не нужно считать, что хабар всегда одно прилагательное: им может быть существительное или предложная группа. Главное — определить, что именно сообщается о мубтада.', 1, 'rule', 'Это продолжение урока 16. Авторский ключ прямо указывает: новых конструкций нет. Суть правила. الْمُبْتَدَأُ — то, о чём говорится; الْخَبَرُ — сообщение о нём. В простой именной фразе оба обычно стоят в именительном падеже. الْبَيْتُ كَبِي'),
('Мединский курс (Том 1)', '17', 'تَثْبِيتُ قَاعِدَةِ جَمْعِ غَيْرِ الْعَاقِلِ (закрепление согласования неразумного множественного)', '<ul><li><b>هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ.</b> — Это японские компании.</li><li><b>الْقُمُصُ رَخِيصَةٌ.</b> — Рубашки дешёвые.</li></ul><br><br>Следует тренировать замену подлежащего на множественное, подбор сказуемого женского единственного и словарные формы ломаного множественного. Например, у <b>حِمَارٌ</b> возможны формы <b>حُمُرٌ</b> и <b>حَمِيرٌ</b>.', 2, 'rule', 'هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ. — Это японские компании. الْقُمُصُ رَخِيصَةٌ. — Рубашки дешёвые. Следует тренировать замену подлежащего на множественное, подбор сказуемого женского единственного и словарные формы ломаного множественного. На'),
('Мединский курс (Том 1)', '18', 'الْمُثَنَّى وَعَلَامَةُ الرَّفْعِ: ـَانِ (двойственное число в именительном падеже)', 'Двойственное число обозначает ровно два предмета или лица. В именительном падеже к основе добавляется <b>ـَانِ</b>.<br><br><ul><li><b>وَلَدٌ ← وَلَدَانِ</b> — мальчик → два мальчика.</li><li><b>بِنْتٌ ← بِنْتَانِ</b> — девочка → две девочки.</li><li><b>هَذَانِ كِتَابَانِ جَدِيدَانِ.</b> — Это две новые книги.</li><li><b>هَاتَانِ سَيَّارَتَانِ جَدِيدَتَانِ.</b> — Это две новые машины.</li></ul><br><br>Определение при двойственном существительном тоже ставится в двойственное число.<br><br><b>Дополнительное объяснение.</b> Винительный и родительный падежи двойственного имеют окончание <b>ـَيْنِ</b>: <b>رَأَيْتُ طَالِبَيْنِ، مَرَرْتُ بِطَالِبَيْنِ</b>. Хотя основной материал урока сосредоточен на <b>ـَانِ</b>, база не должна утверждать, что это единственное окончание двойственного.', 1, 'rule', 'Двойственное число обозначает ровно два предмета или лица. В именительном падеже к основе добавляется ـَانِ . وَلَدٌ ← وَلَدَانِ — мальчик → два мальчика. بِنْتٌ ← بِنْتَانِ — девочка → две девочки. هَذَانِ كِتَابَانِ جَدِيدَانِ. — Это две '),
('Мединский курс (Том 1)', '18', 'كَمِ الِاسْتِفْهَامِيَّةُ وَتَمْيِيزُهَا (вопрос «сколько?»)', 'После вопросительного <b>كَمْ</b> считаемое слово в модели урока ставится в единственном числе винительного падежа.<br><br><ul><li><b>كَمْ كِتَابًا عِنْدَكَ؟</b> — Сколько у тебя книг?</li><li><b>كَمْ سَيَّارَةً عِنْدَ الْمُدِيرِ؟</b> — Сколько машин у директора?</li></ul><br><br>Слово после <b>كَمْ</b> называется <b>تَمْيِيزٌ</b>. У слова с <b>ة</b> добавочная алиф винительного танвина не пишется: <b>سَيَّارَةً</b>, не <b>سَيَّارَةًا</b>.', 2, 'rule', 'После вопросительного كَمْ считаемое слово в модели урока ставится в единственном числе винительного падежа. كَمْ كِتَابًا عِنْدَكَ؟ — Сколько у тебя книг? كَمْ سَيَّارَةً عِنْدَ الْمُدِيرِ؟ — Сколько машин у директора? Слово после كَمْ наз'),
('Мединский курс (Том 1)', '19', 'الْعَدَدَانِ وَاحِدٌ وَاثْنَانِ (числа один и два)', '<b>وَاحِدٌ</b> обычно стоит после существительного и согласуется с ним: <b>كِتَابٌ وَاحِدٌ</b>. Число два обычно выражено самой двойственной формой, поэтому <b>اِثْنَانِ</b> можно опустить: <b>كِتَابَانِ</b> уже означает «две книги».', 1, 'rule', 'وَاحِدٌ обычно стоит после существительного и согласуется с ним: كِتَابٌ وَاحِدٌ . Число два обычно выражено самой двойственной формой, поэтому اِثْنَانِ можно опустить: كِتَابَانِ уже означает «две книги».'),
('Мединский курс (Том 1)', '19', 'الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُذَكَّرِ (3–10 с существительным мужского рода)', 'С мужским считаемым существительным употребляется форма числа с <b>ة</b>: <b>ثَلَاثَةُ، أَرْبَعَةُ، خَمْسَةُ، سِتَّةُ، سَبْعَةُ، ثَمَانِيَةُ، تِسْعَةُ، عَشَرَةُ</b>.<br><br>Считаемое слово ставится во множественном числе родительного падежа: <b>ثَلَاثَةُ كُتُبٍ، أَرْبَعَةُ بُيُوتٍ، خَمْسَةُ أَقْلَامٍ، عَشَرَةُ رِجَالٍ</b>.<br><br><ul><li><b>عِنْدِي ثَلَاثَةُ كُتُبٍ.</b> — У меня три книги.</li><li><b>رَأَيْتُ خَمْسَةَ رِجَالٍ.</b> — Я видел пятерых мужчин.</li></ul><br><br><b>Дополнительное объяснение.</b> Числительное является <b>مُضَافٌ</b>, а множественное считаемое — <b>مُضَافٌ إِلَيْهِ</b>. Падеж числа зависит от его роли; форма считаемого остаётся родительной.', 2, 'rule', 'С мужским считаемым существительным употребляется форма числа с ة : ثَلَاثَةُ، أَرْبَعَةُ، خَمْسَةُ، سِتَّةُ، سَبْعَةُ، ثَمَانِيَةُ، تِسْعَةُ، عَشَرَةُ . Считаемое слово ставится во множественном числе родительного падежа: ثَلَاثَةُ كُتُبٍ،'),
('Мединский курс (Том 1)', '20', 'الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُؤَنَّثِ (3–10 с существительным женского рода)', 'С существительным женского рода употребляется форма числа без <b>ة</b>: <b>ثَلَاثُ، أَرْبَعُ، خَمْسُ، سِتُّ، سَبْعُ، ثَمَانِي، تِسْعُ، عَشْرُ</b>.<br><br><ul><li><b>ثَلَاثُ بَنَاتٍ</b> — три девочки.</li><li><b>أَرْبَعُ أَخَوَاتٍ</b> — четыре сестры.</li><li><b>خَمْسُ أُمَّهَاتٍ</b> — пять матерей.</li><li><b>سَبْعُ طَالِبَاتٍ</b> — семь студенток.</li><li><b>عَشْرُ نِسَاءٍ</b> — десять женщин.</li></ul><br><br>Считаемое слово, как и в уроке 19, стоит во множественном числе родительного падежа.<br><br><b>Определение рода.</b> Род числительного выбирается по форме единственного числа: <b>بَيْتٌ</b> — мужской род, поэтому <b>ثَلَاثَةُ بُيُوتٍ</b>; <b>سَيَّارَةٌ</b> — женский род, поэтому <b>ثَلَاثُ سَيَّارَاتٍ</b>.<br><br><b>Формы чисел.</b> Женские соответствия <b>وَاحِدٌ، اِثْنَانِ</b>: <b>وَاحِدَةٌ، اِثْنَتَانِ</b>.', 1, 'rule', 'С существительным женского рода употребляется форма числа без ة : ثَلَاثُ، أَرْبَعُ، خَمْسُ، سِتُّ، سَبْعُ، ثَمَانِي، تِسْعُ، عَشْرُ . ثَلَاثُ بَنَاتٍ — три девочки. أَرْبَعُ أَخَوَاتٍ — четыре сестры. خَمْسُ أُمَّهَاتٍ — пять матерей. سَبْ'),
('Мединский курс (Том 1)', '21', 'دَرْسُ مُرَاجَعَةٍ (контрольный урок)', 'Авторский ключ прямо указывает: новых грамматических конструкций нет. Урок проверяет пройденные темы и вводит несколько слов, среди которых <b>الْآنَ</b> — сейчас, <b>قَالَ</b> — он сказал, <b>آسِيَا</b> — Азия.<br><br>В базе правил урок 21 не следует заполнять вымышленным новым правилом. Его назначение:<br><br><ul><li>повторение местоимений и суффиксов;</li><li>повторение прошедшего времени;</li><li>повторение идафы, прилагательных, множественного числа и числительных;</li><li>диагностический тест перед темой <b>الْمَمْنُوعُ مِنَ الصَّرْفِ</b>.</li></ul><br><br>Пример повторения:<br><br><ul><li><b>قَالَ الْمُدَرِّسُ: هَؤُلَاءِ طُلَّابٌ جُدُدٌ.</b> — Учитель сказал: «Это новые студенты».</li></ul><br><br>Следовательно, правило <b>لِأَنَّ</b> нельзя относить к уроку 21 первого тома: в авторском поурочном ключе этого урока такой новой конструкции нет.', 1, 'note', 'Авторский ключ прямо указывает: новых грамматических конструкций нет. Урок проверяет пройденные темы и вводит несколько слов, среди которых الْآنَ — сейчас, قَالَ — он сказал, آسِيَا — Азия. В базе правил урок 21 не следует заполнять вымышл'),
('Мединский курс (Том 1)', '22', 'الْمَمْنُوعُ مِنَ الصَّرْفِ: عَدَمُ التَّنْوِينِ (диптоты: отсутствие танвина)', '<b>Суть правила.</b> Некоторые существительные и прилагательные не принимают танвин. В именительном падеже у них одна дамма: <b>أَحْمَدُ، مَسَاجِدُ</b>, а не <b>أَحْمَدٌ، مَسَاجِدٌ</b>.<br><br><b>Дополнительное объяснение.</b> Термин <b>مَمْنُوعٌ مِنَ الصَّرْفِ</b> не означает «совсем не изменяется». Такое слово изменяется по падежам, но обычно не имеет танвина и в родительном падеже без артикля/идафы получает фатху.<br><br>Группы, перечисленные в уроке:<br><br>1. Женские собственные имена: <b>آمِنَةُ، زَيْنَبُ</b>.<br>2. Мужские имена с конечной <b>ة</b>: <b>حَمْزَةُ، مُعَاوِيَةُ</b>.<br>3. Мужские имена на <b>ـَانُ</b>: <b>عُثْمَانُ، سُلَيْمَانُ</b>.<br>4. Прилагательные на <b>فَعْلَانُ</b>: <b>عَطْشَانُ، غَضْبَانُ</b>.<br>5. Мужские имена на модели <b>أَفْعَلُ</b>: <b>أَحْمَدُ، أَكْرَمُ</b>.<br>6. Цвета и подобные прилагательные на <b>أَفْعَلُ</b>: <b>أَحْمَرُ، أَسْوَدُ، أَصْفَرُ، أَبْيَضُ</b>.<br>7. Большинство иноязычных собственных имён: <b>إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، بَغْدَادُ</b>; применяются оговорённые в уроке исключения.<br>8. Некоторые модели ломаного множественного <b>صِيغَةُ مُنْتَهَى الْجُمُوعِ</b>, например <b>مَسَاجِدُ، مَفَاتِيحُ، فَنَادِقُ، دَقَائِقُ</b>.<br><br>База не должна формулировать это как «все женские имена» или «все иностранные слова» без условий.', 1, 'rule', 'Суть правила. Некоторые существительные и прилагательные не принимают танвин. В именительном падеже у них одна дамма: أَحْمَدُ، مَسَاجِدُ , а не أَحْمَدٌ، مَسَاجِدٌ . Дополнительное объяснение. Термин مَمْنُوعٌ مِنَ الصَّرْفِ не означает «с'),
('Мединский курс (Том 1)', '23', 'جَرُّ الْمَمْنُوعِ مِنَ الصَّرْفِ بِالْفَتْحَةِ (родительный падеж диптота с фатхой)', 'Если слово <b>مَمْنُوعٌ مِنَ الصَّرْفِ</b> стоит после предлога или как второй член идафы, но не имеет <b>أَلْـ</b> и само не является первым членом идафы, оно получает фатху вместо касры.<br><br><ul><li><b>أَحْمَدُ</b> — Ахмад, именительный: <b>هَذَا أَحْمَدُ.</b></li><li><b>أَحْمَدَ</b> — Ахмада, винительный: <b>رَأَيْتُ أَحْمَدَ.</b></li><li><b>أَحْمَدَ</b> — Ахмада, родительный после предлога: <b>مَرَرْتُ بِأَحْمَدَ.</b></li><li><b>مِنْ بَغْدَادَ</b> — из Багдада.</li><li><b>فِي فَنَادِقَ</b> — в гостиницах.</li></ul>', 1, 'rule', 'Если слово مَمْنُوعٌ مِنَ الصَّرْفِ стоит после предлога или как второй член идафы, но не имеет أَلْـ и само не является первым членом идафы, оно получает фатху вместо касры. أَحْمَدُ — Ахмад, именительный: هَذَا أَحْمَدُ. أَحْمَدَ — Ахмада'),
('Мединский курс (Том 1)', '23', 'عَوْدُ الْكَسْرَةِ مَعَ أَلْـ أَوِ الْإِضَافَةِ (возвращение касры с артиклем или в идафе)', 'Диптот получает обычную касру в родительном падеже, если он определён артиклем или является первым членом идафы.<br><br><ul><li><b>فِي الْمَسَاجِدِ</b> — в мечетях.</li><li><b>فِي مَسَاجِدِ الْمَدِينَةِ</b> — в мечетях города.</li><li><b>مَفَاتِيحُ الْفَنَادِقِ</b> — ключи гостиниц; здесь <b>الْفَنَادِقِ</b> имеет артикль.</li></ul><br><br><b>Сводная таблица:</b><br><br><table><thead><tr><th>Условие</th><th>Именительный</th><th>Винительный</th><th>Родительный</th></tr></thead><tbody><tr><td>Обычное трёхпадежное слово</td><td><b>ـٌ</b></td><td><b>ـً</b></td><td><b>ـٍ</b></td></tr><tr><td>Диптот без <b>أَلْـ</b> и не в позиции первого члена идафы</td><td><b>ـُ</b></td><td><b>ـَ</b></td><td><b>ـَ</b></td></tr><tr><td>Диптот с <b>أَلْـ</b> или как первый член идафы</td><td><b>ـُ</b></td><td><b>ـَ</b></td><td><b>ـِ</b></td></tr></tbody></table><br><br>## Обязательные требования к импорту этой базы<br><br>1. Создать ровно 23 урока первого тома; не создавать отдельный 24-й урок для части 4A.<br>2. Хранить каноническое название урока отдельно от методического подзаголовка.<br>3. Не показывать лексику или правила будущего урока в более раннем уроке.<br>4. Хранить арабский текст в Unicode NFC. Огласовки должны быть частью эталона, но режим проверки может отдельно оценивать буквы и огласовки.<br>5. Не смешивать самостоятельные местоимения <b>هُمْ، هُنَّ</b> с присоединяемыми суффиксами <b>ـهُمْ، ـهُنَّ</b>.<br>6. У каждого правила хранить: источник, номер урока, уровень объяснения, примеры, разбор, статус проверки и версию.<br>7. Уроки 11, 17 и 21 должны быть помечены как повторительные/закрепляющие; им нельзя приписывать посторонние новые правила.<br>8. Перед удалением старой базы сделать экспорт и проверить новую базу в тестовой копии.', 2, 'rule', 'Диптот получает обычную касру в родительном падеже, если он определён артиклем или является первым членом идафы. فِي الْمَسَاجِدِ — в мечетях. فِي مَسَاجِدِ الْمَدِينَةِ — в мечетях города. مَفَاتِيحُ الْفَنَادِقِ — ключи гостиниц; здесь ال');
